import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"Resources","description":"","frontmatter":{},"headers":[],"relativePath":"en/resourcer.md","filePath":"en/resourcer.md"}`),a={name:`en/resourcer.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to “Resources”">​</a></h1><p>There are many different websites and forums with information about DIY hormone therapy. One of the largest resources is <a href="https://www.reddit.com/r/TransDIY/" target="_blank" rel="noreferrer">r/TransDIY</a>. Their <a href="https://www.reddit.com/r/transDIY/wiki/index/" target="_blank" rel="noreferrer">wiki</a> and <a href="https://www.reddits://www.reddit.com/r/r/transDIY/wiki/index/" target="_blank" rel="noreferrer">FAQ</a> have really great information about DIY hormone therapy and are a great place to start. If reddit says you need to verify your identity to see it, I would recommend using a VPN or using a reddit frontend like <a href="https://http.com/redlib-ordlib-instances/blob/main/instances.md" target="_blank" rel="noreferrer">Redlib</a>.</p><p>Another really good website is <a href="https://diyhrt.info/" target="_blank" rel="noreferrer">diyhrt.info</a>. They have a lot of information about DIY hormone therapy, and I would recommend that you read their entire transfem/transmac guide if you are interested in DIY hormone therapy or just hormone therapy in general.</p><p><a href="https://transharmreduction.org/" target="_blank" rel="noreferrer">Trans Harm Reduction</a> is a really good website for various things, but one of the most important things they do is testing the hormones from different sellers so we can be sure that the hormones are safe and effective.</p><p><a href="https://transfemscience.org/" target="_blank" rel="noreferrer">TransfemScience</a> is another great page with lots of information about hormone therapy. I would highly recommend reading their article <a href="https://transfemscience.org/articles/transfem-intro/" target="_blank" rel="noreferrer">An Introduction to Hormone Therapy for Transfeminine People</a> as it has lots of important information which is good to know if you want to start DIY hormone therapy.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};